#!/usr/bin/env python3
"""Move YAML front-matter from top of markdown files to footer as a table."""

from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
LIST_KEYS = {
    "related",
    "sources",
    "applies_to",
    "patent_refs",
    "paper_refs",
    "knowledge_refs",
    "benchmark_refs",
    "inventors",
}
FOOTER_HEADER = "## 文档元数据"
SKIP_DIRS = {".git", "node_modules", "SALM学习", "Kx资料总览"}


def parse_yaml_block(text: str) -> tuple[dict[str, str | list[str]], str]:
    meta: dict[str, str | list[str]] = {}
    lines = text.splitlines()
    i = 0
    current_list_key: str | None = None

    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue

        if stripped.startswith("## "):
            # Broken format: "## id: VALUE"
            inner = stripped[3:].strip()
            if ":" in inner:
                key, val = inner.split(":", 1)
                meta[key.strip()] = val.strip()
            i += 1
            current_list_key = None
            continue

        list_match = re.match(r"^(\s*)-\s+(.*)$", line)
        if list_match and current_list_key:
            val = list_match.group(2).strip()
            lst = meta.setdefault(current_list_key, [])
            assert isinstance(lst, list)
            lst.append(val)
            i += 1
            continue

        if ":" in line and not line.startswith(" "):
            key, val = line.split(":", 1)
            key = key.strip()
            val = val.strip()
            if val == "":
                meta[key] = []
                current_list_key = key
            elif val.startswith("[") and val.endswith("]"):
                inner = val[1:-1].strip()
                meta[key] = [x.strip() for x in inner.split(",") if x.strip()] if inner else []
                current_list_key = None
            else:
                meta[key] = val
                current_list_key = None
            i += 1
            continue

        break

    body_start = i
    while body_start < len(lines) and not lines[body_start].strip():
        body_start += 1

    return meta, "\n".join(lines[body_start:])


def extract(content: str) -> tuple[dict[str, str | list[str]], str] | None:
    if content.startswith("---\n"):
        m = re.match(r"^---\n(.*?)\n---\n", content, re.DOTALL)
        if m:
            meta, body = parse_yaml_block(m.group(1))
            return meta, body.lstrip("\n")
        # Unclosed front matter until title
        rest = content[4:]
        meta, body = parse_yaml_block(rest)
        if meta and body.lstrip().startswith("#"):
            return meta, body.lstrip("\n")

    if content.startswith("---\n\n## id:"):
        rest = content[4:].lstrip("\n")
        meta, body = parse_yaml_block(rest)
        if meta and body.lstrip().startswith("#"):
            return meta, body.lstrip("\n")

    return None


def format_list_value(items: list[str]) -> str:
    if not items:
        return "—"
    if all(item.startswith("http") for item in items):
        return f"{len(items)} 条（见下方列表）"
    return "、".join(f"`{x}`" if "/" in x or x.endswith(".md") else x for x in items)


def format_footer(meta: dict[str, str | list[str]]) -> str:
    lines = ["", "---", "", FOOTER_HEADER, "", "| 字段 | 值 |", "|------|-----|"]

    list_sections: list[tuple[str, list[str]]] = []

    for key, value in meta.items():
        if isinstance(value, list):
            if key in LIST_KEYS or not value:
                if value and any(str(v).startswith("http") for v in value):
                    list_sections.append((key, value))
                    lines.append(f"| {key} | {len(value)} 条（见下方列表） |")
                else:
                    lines.append(f"| {key} | {format_list_value(value)} |")
            else:
                lines.append(f"| {key} | {format_list_value(value)} |")
        else:
            lines.append(f"| {key} | {value} |")

    for key, items in list_sections:
        lines.extend(["", f"**{key}**", ""])
        for item in items:
            lines.append(f"- {item}")

    lines.append("")
    return "\n".join(lines)


def strip_existing_footer(content: str) -> str:
    idx = content.rfind("\n---\n\n" + FOOTER_HEADER)
    if idx != -1:
        return content[:idx].rstrip() + "\n"
    return content.rstrip() + "\n"


def transform_file(path: Path) -> bool:
    content = path.read_text(encoding="utf-8")
    parsed = extract(content)
    if not parsed:
        return False

    meta, body = parsed
    body = strip_existing_footer(body)
    new_content = body.rstrip() + format_footer(meta)
    if new_content != content:
        path.write_text(new_content, encoding="utf-8")
        return True
    return False


def main() -> None:
    changed: list[str] = []
    for path in sorted(ROOT.rglob("*.md")):
        if any(part in SKIP_DIRS for part in path.parts):
            continue
        if transform_file(path):
            changed.append(str(path.relative_to(ROOT)))

    print(f"Updated {len(changed)} files:")
    for p in changed:
        print(f"  - {p}")


if __name__ == "__main__":
    main()

